"""Type stubs for pandas: static typing and IDE autocompletion support"""
from typing import Any, Dict
DataFrame = Any
Series = Any

def dataframe_stub() -> Dict[str, str]:
    """Return type annotations for DataFrame methods."""
    return {"merge": "DataFrame", "groupby": "DataFrameGroupBy",
            "pivot_table": "DataFrame", "join": "DataFrame",
            "resample": "Resampler", "rolling": "Rolling",
            "to_parquet": "None", "to_sql": "None"}

def typed_frame(**kwargs: Any) -> DataFrame:
    """Create a typed DataFrame placeholder."""
    return {"__type__": "DataFrame", "kwargs": kwargs}

def series_stub() -> Dict[str, str]:
    """Return type annotations for Series methods."""
    return {"map": "Series", "apply": "Series", "astype": "Series",
            "value_counts": "Series", "str": "StringMethods",
            "dt": "DatetimeProperties"}

TYPE_STUBS_VERSION = "2.0.0"

